function networkChrome(){const authbar=document.querySelector('#authbar');if(authbar)document.querySelector('.nav').append(authbar);const brand=document.querySelector('.brand');if(brand){const mark=el('img');mark.src='assets/community-mark.svg';mark.alt='';mark.width=42;mark.height=42;const words=el('span',null,'brand-words'),name=el('span',null,'brand-name');name.append(el('span','Heavenly Key'),el('span',' Global','brand-global'));words.append(name,el('small','FAITH · FELLOWSHIP · PURPOSE'));brand.replaceChildren(mark,words);}if(!document.querySelector('.skip-community')){const skip=el('a','Skip to community content','skip-community');skip.href='#page-root';document.body.prepend(skip);root.tabIndex=-1;}const nav=document.querySelector('.navlinks');nav.replaceChildren();for(const [label,href,key] of [['Home','index.html','home'],['Groups','groups.html','groups'],['Spaces','spaces.html','spaces'],['Messages','messages.html','messages']]){const a=el('a',label);a.href=href;if(page===key)a.setAttribute('aria-current','page');nav.append(a);}const people=el('a','Find people','nav-people');people.href='index.html#discover';nav.append(people);const dock=el('nav',null,'mobile-dock');dock.setAttribute('aria-label','Primary navigation');for(const [icon,label,href,key] of [['⌂','Home','index.html','home'],['◉','Groups','groups.html','groups'],['▧','Spaces','spaces.html','spaces'],['✉','Messages','messages.html','messages']]){const a=el('a',null);a.href=href;a.append(el('span',icon),el('small',label));if(page===key)a.setAttribute('aria-current','page');dock.append(a);}const more=el('details',null,'mobile-more'),toggle=el('summary'),menu=el('div',null,'mobile-more-menu');toggle.append(el('span','☰'),el('small','More'));toggle.setAttribute('aria-label','More network navigation');more.append(toggle,menu);for(const [icon,label,href,key] of [['◇','Fellowship','fellowship.html','fellowship'],['✦','Prayer','prayer.html','prayer'],['✧','Grow in Christ','grow.html','grow'],['↗','Missions','missions.html','missions'],['◎','My profile','profile.html','profile'],['⌕','Find people','index.html#discover','discover'],['◇','Safety & privacy','safety.html','safety'],['⚙','Account & security','account.html','account']]){const a=el('a',null);a.href=href;a.append(el('span',icon),document.createTextNode(label));if(page===key){a.setAttribute('aria-current','page');toggle.classList.add('current');}menu.append(a);}dock.append(more);document.addEventListener('click',e=>{if(!more.contains(e.target))more.open=false;});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&more.open){more.open=false;toggle.focus();}});document.body.append(dock);const safety=el('a','Safety & privacy');safety.href='safety.html';document.querySelector('.bottom-nav')?.append(safety);}
function notificationLink(n){const fallback=n.kind==='message'||n.kind==='message_request'?'messages.html':'index.html';if(!n.href||!/^\/(?!\/)/.test(n.href))return fallback;const url=new URL(n.href,location.origin);if(url.origin!==location.origin)return fallback;if(url.pathname==='/messages')url.pathname='/messages.html';if(!/^\/[a-z-]+\.html$/.test(url.pathname))return fallback;return url.pathname+url.search;}
async function networkNotifications(){
 notificationEvents?.abort();notificationEvents=new AbortController();const eventOptions={signal:notificationEvents.signal};if(!session)return;const details=el('details',null,'notifications'),summary=el('summary','Notifications'),list=el('div',null,'notification-list');details.append(summary,list);document.querySelector('#authbar').prepend(details);
 let cached=null,loading=false;const badge=count=>{summary.textContent='Notifications'+(count?' · '+(count>99?'99+':count):'');summary.setAttribute('aria-label',count+' unread notifications');};
 async function fetchNotifications(){const d=await api('/api/notifications');cached=d;badge(d.unreadCount||0);return d;}
 async function mark(ids){const d=await api('/api/notifications/read','POST',{ids});badge(d.unreadCount||0);for(const n of cached?.items||[])if(ids.includes(n.notification_id))n.read_at='read';}
 function render(){
 list.replaceChildren();const rows=(cached?.items||[]).slice(0,20);
 if(rows.some(n=>!n.read_at)){const read=el('button','Mark listed notifications as read','btn secondary');read.type='button';read.addEventListener('click',async()=>{read.disabled=true;try{await mark(rows.filter(n=>!n.read_at).map(n=>n.notification_id));render();}catch(err){list.append(el('p',err.message,'status'));read.disabled=false;}});list.append(read);}
 for(const n of rows){const link=el('a',null,'notification-item'+(!n.read_at?' unread':''));link.href=notificationLink(n);link.append(el('strong',n.title),el('small',n.body||''),el('time',dateTime(n.created_at).toLocaleString()));link.addEventListener('click',async e=>{if(e.ctrlKey||e.metaKey||e.shiftKey||e.altKey)return;e.preventDefault();if(!n.read_at)try{await mark([n.notification_id]);}catch{}navigate(link.href);});list.append(link);}
 if(!rows.length)list.append(el('p','You are all caught up.','muted'));
 }
 details.addEventListener('toggle',async()=>{if(!details.open||loading)return;loading=true;if(!cached)list.replaceChildren(el('p','Loading notifications…'));else render();try{await fetchNotifications();if(details.open)render();}catch(err){list.replaceChildren(el('p',err.message,'status'));}finally{loading=false;}});
 document.addEventListener('click',e=>{if(!details.contains(e.target))details.open=false;},eventOptions);document.addEventListener('keydown',e=>{if(e.key==='Escape'&&details.open){details.open=false;summary.focus();}},eventOptions);
 try{await fetchNotifications();}catch{} // No background notification polling.
}

async function mountSafety(){
 root.append(card("Our purpose in Christ","This community advances the gospel of Christ, equips the saints, upholds the faith of our fathers, and encourages meaningful, purposeful lives that fulfill destiny and the will of God."));
 const intro=card("Keeping our community healthy is everyone's responsibility","Report anything against our Christ-centered values immediately using Report in a post’s menu. General reports go to site administrators and moderators. Group reports go to group managers and site staff; a group decision does not close site review. Report honestly; a report does not automatically remove content. Block members to stop contact. If someone faces immediate danger, contact local emergency services. This platform is not an emergency service.");root.append(intro);
 const rules=card("Community rules","No pornography or sexual exploitation, child abuse, threats, hate, harassment, fraud, impersonation, doxxing or unlawful content. Respect privacy and intellectual property. Christian teaching and respectful fellowship are welcome. Automated text checks flag suspicious content for human review, hold ambiguous posts or messages, and block clear prohibited text. They can make mistakes and do not scan video content or understand every language. A site administrator must approve an account lock. Locked members can still sign in to read the reason and request review in this page.");root.append(rules);
 const privacy=card("Your privacy","Your display name, bio and public posts can be viewed by anyone. Your full name is visible to you. Location, church, work and birthday follow your profile settings. Connections-only information is visible to people YOU connect to; another person following you does not unlock it. Religious and prayer information can be sensitive: share only what you choose. Private ministry prayer items currently stay visible only to their author.");const edit=el("a","Review profile privacy","btn secondary");edit.href="profile.html";privacy.append(edit);privacy.append(el("p","We store account details, password hashes, content, connections, messages, reports and safety decisions to operate the service. Authorized staff review reported content, including a reported message; ordinary members cannot browse other conversations. Messages are not end-to-end encrypted. Cloudflare provides hosting and storage. Optional Google and Facebook sign-in stores a provider identifier linked to your profile; provider access tokens are used for verification and are not retained. You can keep using email sign-in. Clearly labelled sponsored adverts may link to other sites; those sites have their own privacy policies. Advert images are stored on this community. Video players contact YouTube or Facebook only after you choose Play; their privacy policies apply. Voice calls, video calls and voice notes are currently unavailable. Deleted or restricted content may remain in storage pending retention and legal review."));root.append(privacy);
 root.append(card("Account and legal requests","Use the request form below for access, deletion, correction, privacy concerns or an appeal. Requests go to authorized administrators and are not immediate automatic deletion. Do not include identity documents, passwords or copies of illegal material. New accounts are for adults aged 18 or older. This uses self-declaration, not verified identity. Country-specific rights, age assurance, retention periods and formal authority contact arrangements still require operator approval and legal review. Authorities must use lawful, verified procedures; claiming to be law enforcement does not grant account access."));
 if(!session){const publicLegal=card("Sign in to send a private request","Sign in to use the private request form. Public privacy, terms and lawful-authority request information is available on the ministry website.");const legalLink=el("a","Open public legal request information","btn secondary");legalLink.href="https://www.heavenlykey.org/pages/legal-requests.html";legalLink.target="_blank";legalLink.rel="noopener noreferrer";publicLegal.append(legalLink);root.append(publicLegal);return;}
 const data=await api("/api/me/safety");for(const r of data.restrictions||[])root.append(card("Account review · "+r.status,r.reason+" Use Safety concern below to request a review of this account decision."));const form=el("form",null,"stack"),box=card("Send a private request");field(form,"Request type","kind","select",{options:[["privacy","Privacy concern"],["access","Access to my data"],["deletion","Delete my data"],["correction","Correct my data"],["safety","Safety concern"],["appeal","Appeal a decision"]]});field(form,"Decision to appeal","decisionId","select",{options:[["","Choose if appealing"],...(data.decisions||[]).filter(x=>x.action==='remove').map(x=>[String(x.decision_id),"Decision "+x.decision_id+" · "+x.reason])]});field(form,"Details","details","textarea",{required:true,maxLength:3000});const send=el("button","Submit request","btn primary"),st=el("p","","status");send.type="submit";form.append(send,st);form.addEventListener("submit",async e=>{e.preventDefault();send.disabled=true;try{const d=await api("/api/me/requests","POST",Object.fromEntries(new FormData(form)));status(st,"Request #"+d.requestId+" received. Check this page for a response.");}catch(err){status(st,err.message);}finally{send.disabled=false;}});box.append(form);root.append(box);
 const history=card("My decisions and requests");for(const d of data.decisions||[])history.append(el("p","Decision #"+d.decision_id+" · "+d.action+" · "+d.reason));for(const r of data.requests||[])history.append(el("p","Request #"+r.request_id+" · "+r.kind+" · "+r.status+" · "+(r.response||"Awaiting review")));root.append(history);
 await moderatorReports();await stewardshipPanel();
 if(['administrator','owner'].includes(session.user.role)){const queue=await api("/api/moderation/requests"),admin=card("Administrator request queue","Keep responses specific. Confirm deletion or access requests only after carrying out the appropriate verified action. Another administrator must review an appeal of your own decision.");for(const r of queue.items||[]){const item=el("form",null,"stack item");item.append(el("h3","Request #"+r.request_id+" · "+r.kind),el("p",r.display_name),el("p",r.details));field(item,"Response","response","textarea",{required:true,maxLength:3000});if(r.kind==='appeal')field(item,"Restore content after successful appeal","restore","checkbox");const b=el("button","Record response","btn secondary"),msg=el("p","","status");b.type="submit";item.append(b,msg);item.addEventListener("submit",async e=>{e.preventDefault();b.disabled=true;try{await api("/api/moderation/requests/"+r.request_id,"POST",{response:item.elements.response.value,restore:!!item.elements.restore?.checked});item.replaceChildren(el("p","Response recorded."));}catch(err){status(msg,err.message);b.disabled=false;}});admin.append(item);}root.append(admin);}
}
