 function render(){const items=themes[select.value],i=Math.floor(Date.now()/86400000)%items.length,[ref,text,action]=items[i];body.replaceChildren(el('strong',ref),el('p',text),el('p','Put faith into action: '+action));current=ref+'\n'+text+'\n'+action;status(st,'');}
 select.addEventListener('change',render);copy.type='button';copy.addEventListener('click',async()=>{try{await navigator.clipboard.writeText(current);status(st,'Copied. Read the Scripture and personalize the encouragement before sharing.');}catch{status(st,'Select the text above to copy it.');}});c.append(select,body,copy,st,el('small','Prepared reflections, not Scripture quotations or AI-generated prophecy. Read the referenced passage in your Bible.','muted'));render();return c;
